import re
import datetime

from ta_moler.events.rtg_ctrl.genericrtg_ctrl_lineevent import GenericRtgCtrlLineEvent


class TimeShiftDetected(GenericRtgCtrlLineEvent):
    """Time shift detected event class."""

    # Example line: [  500.029628] platform[874]: ccs: SCH(1239): FATAL ERROR handleCriticalTimeShift(): ClockTicker error - LTE Time shift detected, expectedTime=[509.7] receivedTime=[768.4] ticksDiff=898444
    _re_time_shift_detected = \
        re.compile(r'FATAL ERROR handleCriticalTimeShift\(\): ClockTicker error - LTE Time shift detected')

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for time shift detected.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(TimeShiftDetected, self).__init__(connection=connection, runner=runner,
                                                till_occurs_times=till_occurs_times,
                                                detect_patterns=[self._re_time_shift_detected],
                                                match='any')


EVENT_OUTPUT = """[  204.215579] platform[874]: ccs:
[  500.029628] platform[874]: ccs: SCH(1239): FATAL ERROR handleCriticalTimeShift(): ClockTicker error - LTE Time shift detected, expectedTime=[509.7] receivedTime=[768.4] ticksDiff=898444
[  500.030247] platform[874]: ccs: SCH(123b): FATAL ERROR handleCriticalTimeShift(): ClockTicker error - LTE Time shift detected, expectedTime=[509.7] receivedTime=[768.4] ticksDiff=898498
[  512.840587] platform[874]: ccs: CCSLiteExe 0x1239 has crashed. Core dump /var/tmp/diagn/CCSLiteExe_5955_.core.xz"""

EVENT_KWARGS = {"till_occurs_times": 1}

EVENT_RESULT = [{
    'line': '[  500.029628] platform[874]: ccs: SCH(1239): FATAL ERROR handleCriticalTimeShift(): ClockTicker error - LTE Time shift detected, expectedTime=[509.7] receivedTime=[768.4] ticksDiff=898444',
    'groups': (),
    'named_groups': {},
    'matched': 'FATAL ERROR handleCriticalTimeShift(): ClockTicker error - LTE Time shift detected',
    'time': datetime.datetime.now()}]
